// test/type-docs.test.mjs · the type reference (reference/types/) is generated by scripts/type-docs.mjs. Every page's minimal
// example passes the checker, every page is complete, and the pages are what the generator gives.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { execFileSync } from 'node:child_process';
import { generate } from '../scripts/schema.mjs';
import { wrap, problems } from '../scripts/type-docs.mjs';
import { checkConfig } from '../scripts/lib.mjs';

const HERE = new URL('..', import.meta.url);
const read = (p) => fs.readFileSync(new URL(p, HERE), 'utf8');
const types = generate().schema.$defs.widget.oneOf.map((o) => o.$ref.split('/').pop());
const page = (t) => read(`reference/types/${t}.md`);
const section = (md, name) => { const m = new RegExp(`^## ${name}\\n([\\s\\S]*?)(?=^## |(?![\\s\\S]))`, 'm').exec(md); return m ? m[1] : ''; };

test('type-docs: a page for each of the twenty types, and an index that links to each', () => {
  assert.equal(types.length, 20);
  const index = read('reference/types/README.md');
  for (const t of types) {
    assert.ok(fs.existsSync(new URL(`reference/types/${t}.md`, HERE)), `reference/types/${t}.md`);
    assert.ok(index.includes(`[${t}.md](${t}.md)`), `the index links ${t}`);
  }
});

test('type-docs: every page has its sections, prose and no placeholder', () => {
  for (const t of types) {
    const md = page(t);
    assert.ok(md.startsWith(`# \`${t}\`\n`), `${t}: title`);
    for (const h of ['When to use', 'Gotchas', 'Minimal example', 'Keys', 'The checker rejects']) assert.ok(section(md, h), `${t}: "${h}" is empty or missing`);
    assert.ok(!/TODO/.test(md), `${t}: a TODO is left`);
    const gotchas = section(md, 'Gotchas').split('\n').filter((l) => l.startsWith('- '));
    assert.ok(gotchas.length >= 3 && gotchas.length <= 6, `${t}: 3 to 6 gotchas (has ${gotchas.length})`);
    const rejects = section(md, 'The checker rejects').split('\n').filter((l) => /^\| [^-C]/.test(l));
    assert.ok(rejects.length >= 3 && rejects.length <= 5, `${t}: 3 to 5 rejected mistakes (has ${rejects.length})`);
    assert.ok(/<!-- prose -->[\s\S]*<!-- \/prose -->/.test(md), `${t}: prose markers`);
  }
});

test('type-docs: every minimal example passes the checker, and its tag names the widget it draws', () => {
  for (const t of types) {
    const ex = section(page(t), 'Minimal example');
    const json = /```json\n([\s\S]*?)\n```/.exec(ex);
    assert.ok(json, `${t}: a json example`);
    const example = JSON.parse(json[1]);
    const tag = /\[\[(\w+):(\w+)[^\]]*\]\]/.exec(ex);
    assert.ok(tag, `${t}: a tag`);
    const main = example.widgets ? example.widgets[Object.keys(example.widgets).pop()] : example;
    assert.equal(main.type, t, `${t}: the example is a ${t}`);
    if (example.widgets) assert.equal(Object.keys(example.widgets).pop(), tag[2], `${t}: the tag names the last widget`);
    assert.deepEqual(problems(example, tag[1], tag[2]).map((e) => e.message), [], `${t}: the checker accepts the example`);
    assert.deepEqual(checkConfig(wrap(example, tag[1], tag[2])), [], `${t}: check:config accepts it`);
  }
});

test('type-docs: no page points into the private docs', () => {
  for (const f of fs.readdirSync(new URL('reference/types/', HERE))) assert.ok(!/docs\/|examples\/|tools\//.test(read(`reference/types/${f}`)), `${f}: a private path`);
});

test('type-docs: the pages are what scripts/type-docs.mjs gives', () => {
  execFileSync(process.execPath, ['scripts/type-docs.mjs', '--check'], { cwd: HERE.pathname, stdio: 'pipe' });
});
